CREATE TABLE customer(id BIGINT PRIMARY KEY, customer_name VARCHAR(200));
CREATE TABLE sys_user(id BIGINT PRIMARY KEY, username VARCHAR(80), display_name VARCHAR(100), role VARCHAR(20));
CREATE TABLE sales_order(id BIGINT PRIMARY KEY, order_no VARCHAR(50), customer_id BIGINT, status VARCHAR(40));
CREATE TABLE after_sales_order(id BIGINT PRIMARY KEY, after_sales_no VARCHAR(50), customer_id BIGINT, after_sales_type VARCHAR(20), status VARCHAR(30));
CREATE TABLE customer_fund_account(customer_id BIGINT PRIMARY KEY, balance DECIMAL(19,4) NOT NULL, version INT NOT NULL DEFAULT 0, updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE customer_fund_request(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, customer_id BIGINT NOT NULL, request_type VARCHAR(30) NOT NULL, status VARCHAR(20) NOT NULL, amount DECIMAL(19,4) NOT NULL, payment_date DATE, payment_method VARCHAR(60), reference_no VARCHAR(100), source_type VARCHAR(30), source_id BIGINT, remark VARCHAR(1000), review_comment VARCHAR(1000), submitted_by BIGINT, submitted_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, reviewed_by BIGINT, reviewed_at TIMESTAMP, version INT DEFAULT 0);
CREATE TABLE customer_fund_ledger(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, customer_id BIGINT NOT NULL, entry_type VARCHAR(30) NOT NULL, direction VARCHAR(10) NOT NULL, amount DECIMAL(19,4) NOT NULL, balance_before DECIMAL(19,4) NOT NULL, balance_after DECIMAL(19,4) NOT NULL, request_id BIGINT UNIQUE, source_type VARCHAR(30), source_id BIGINT, source_no VARCHAR(80), reverses_ledger_id BIGINT UNIQUE, reason VARCHAR(1000), operated_by BIGINT, operated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
